// The 15.GB repo default exceeds free runner memory, so cellranger would wait for it until the nf-test timeout.
process {
    resourceLimits = [
        memory: 6.GB
    ]

    withName: CELLRANGER_MKGTF {
        ext.args = '--attribute=gene_biotype:protein_coding \
            --attribute=gene_biotype:lincRNA \
            --attribute=gene_biotype:antisense \
            --attribute=gene_biotype:IG_LV_gene \
            --attribute=gene_biotype:IG_V_gene \
            --attribute=gene_biotype:IG_V_pseudogene \
            --attribute=gene_biotype:IG_D_gene \
            --attribute=gene_biotype:IG_J_gene \
            --attribute=gene_biotype:IG_J_pseudogene \
            --attribute=gene_biotype:IG_C_gene \
            --attribute=gene_biotype:IG_C_pseudogene \
            --attribute=gene_biotype:TR_V_gene \
            --attribute=gene_biotype:TR_V_pseudogene \
            --attribute=gene_biotype:TR_D_gene \
            --attribute=gene_biotype:TR_J_gene \
            --attribute=gene_biotype:TR_J_pseudogene \
            --attribute=gene_biotype:TR_C_gene'
    }
    withName: CELLRANGER_COUNT {
        ext.args = '--chemistry SC3Pv3 --create-bam true'
    }
    withName: STAR_STARSOLO {
        ext.args = '--soloUMIlen 12 --outSAMtype BAM SortedByCoordinate --soloBarcodeReadLength 0 --limitBAMsortRAM 5000000000 --outReadsUnmapped Fastx --outWigType bedGraph --outWigStrand Stranded --outWigNorm RPM'
    }
}
